-- Portable SQLite/D1-target source. Local SQLite tests only; NOT HOSTED/APPLIED.
-- No platform roles, RLS, credentials or deployment infrastructure.
PRAGMA foreign_keys=ON;
CREATE TABLE stores(id TEXT PRIMARY KEY CHECK(id IN ('M01','M02')),label TEXT NOT NULL) STRICT;
INSERT INTO stores VALUES('M01','Magasin 1 (M01)'),('M02','Magasin 2 (M02)');
CREATE TABLE accounts(id TEXT PRIMARY KEY,active INTEGER NOT NULL CHECK(active IN(0,1))) STRICT;
CREATE TABLE memberships(user_id TEXT NOT NULL REFERENCES accounts(id),store_id TEXT NOT NULL CHECK(store_id IN('M01','M02','GLOBAL')),role TEXT NOT NULL CHECK(role IN('SUPER_ADMIN','MANAGER','SELLER')),CHECK((role='SUPER_ADMIN')=(store_id='GLOBAL')),PRIMARY KEY(user_id,store_id,role)) STRICT;
CREATE TABLE drawers(id TEXT PRIMARY KEY,store_id TEXT NOT NULL UNIQUE REFERENCES stores(id)) STRICT;
CREATE TABLE shifts(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),drawer_id TEXT NOT NULL REFERENCES drawers(id),seller_id TEXT NOT NULL REFERENCES accounts(id),state TEXT NOT NULL CHECK(state IN('OPEN','CLOSED')),opening_minor INTEGER NOT NULL CHECK(opening_minor BETWEEN 0 AND 99999999999999),counted_minor INTEGER CHECK(counted_minor BETWEEN 0 AND 99999999999999)) STRICT;
CREATE UNIQUE INDEX one_open_drawer ON shifts(drawer_id) WHERE state='OPEN';
CREATE TRIGGER shift_drawer_scope BEFORE INSERT ON shifts WHEN NOT EXISTS(SELECT 1 FROM drawers WHERE id=NEW.drawer_id AND store_id=NEW.store_id) BEGIN SELECT RAISE(ABORT,'DRAWER_SCOPE'); END;
CREATE TABLE customers(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),name TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,UNIQUE(id,store_id)) STRICT;
CREATE TABLE catalog(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('phone','accessory')),sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,attributes_json TEXT NOT NULL CHECK(json_valid(attributes_json))) STRICT;
CREATE TABLE prices(store_id TEXT NOT NULL REFERENCES stores(id),item_id TEXT NOT NULL REFERENCES catalog(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),PRIMARY KEY(store_id,item_id)) STRICT;
CREATE TABLE phones(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),catalog_id TEXT NOT NULL REFERENCES catalog(id),barcode TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN('AVAILABLE','SOLD','IN_TRANSIT','RETURN_BLOCKED')),attributes_json TEXT NOT NULL CHECK(json_valid(attributes_json))) STRICT;
CREATE TABLE phone_identifiers(identifier TEXT PRIMARY KEY CHECK(length(identifier)=15 AND identifier NOT GLOB '*[^0-9]*'),phone_id TEXT NOT NULL REFERENCES phones(id),slot INTEGER NOT NULL CHECK(slot IN(1,2)),UNIQUE(phone_id,slot)) STRICT;
CREATE TABLE accessory_balances(store_id TEXT NOT NULL REFERENCES stores(id),item_id TEXT NOT NULL REFERENCES catalog(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 0 AND 2147483647),PRIMARY KEY(store_id,item_id)) STRICT;
CREATE TABLE commands(key TEXT PRIMARY KEY,actor_id TEXT NOT NULL REFERENCES accounts(id),store_id TEXT NOT NULL REFERENCES stores(id),operation TEXT NOT NULL,payload_hash TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('STARTED','DONE')),transaction_id TEXT NOT NULL,response_json TEXT CHECK(response_json IS NULL OR json_valid(response_json))) STRICT;
CREATE TABLE command_guards(key TEXT NOT NULL REFERENCES commands(key),ok INTEGER NOT NULL CHECK(ok=1)) STRICT;
CREATE TABLE sales(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),store_id TEXT NOT NULL REFERENCES stores(id),shift_id TEXT NOT NULL REFERENCES shifts(id),seller_id TEXT NOT NULL REFERENCES accounts(id),customer_id TEXT,total_minor INTEGER NOT NULL CHECK(total_minor BETWEEN 1 AND 99999999999999),tender TEXT NOT NULL CHECK(tender IN('Cash','Bank')),tendered_minor INTEGER NOT NULL CHECK(tendered_minor BETWEEN 1 AND 99999999999999),change_minor INTEGER NOT NULL CHECK(change_minor BETWEEN 0 AND 99999999999999),bank_reference TEXT,FOREIGN KEY(customer_id,store_id) REFERENCES customers(id,store_id),CHECK((tender='Cash' AND tendered_minor-total_minor=change_minor) OR(tender='Bank' AND tendered_minor=total_minor AND change_minor=0 AND length(trim(bank_reference))>0))) STRICT;
CREATE TABLE sale_lines(sale_id TEXT NOT NULL REFERENCES sales(id),item_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('phone','accessory')),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 2147483647),unit_minor INTEGER NOT NULL CHECK(unit_minor BETWEEN 1 AND 99999999999999),PRIMARY KEY(sale_id,item_id,kind),CHECK(kind<>'phone' OR quantity=1)) STRICT;
CREATE UNIQUE INDEX one_serialized_sale ON sale_lines(item_id) WHERE kind='phone';
CREATE TABLE stock_movements(id TEXT PRIMARY KEY,command_key TEXT NOT NULL REFERENCES commands(key),store_id TEXT NOT NULL REFERENCES stores(id),item_id TEXT NOT NULL,delta INTEGER NOT NULL CHECK(delta<>0),reason TEXT NOT NULL,UNIQUE(command_key,item_id,reason)) STRICT;
CREATE TABLE payments(sale_id TEXT PRIMARY KEY REFERENCES sales(id),method TEXT NOT NULL CHECK(method IN('Cash','Bank')),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999)) STRICT;
CREATE TABLE cash_movements(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),shift_id TEXT NOT NULL REFERENCES shifts(id),seller_id TEXT NOT NULL REFERENCES accounts(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),reason TEXT NOT NULL) STRICT;
CREATE TRIGGER cash_requires_open BEFORE INSERT ON cash_movements WHEN NOT EXISTS(SELECT 1 FROM shifts WHERE id=NEW.shift_id AND state='OPEN') BEGIN SELECT RAISE(ABORT,'SHIFT_CLOSED'); END;
CREATE TABLE audit_events(id TEXT PRIMARY KEY,command_key TEXT NOT NULL UNIQUE REFERENCES commands(key),actor_id TEXT NOT NULL REFERENCES accounts(id),store_id TEXT NOT NULL REFERENCES stores(id),operation TEXT NOT NULL) STRICT;
CREATE TABLE journals(command_key TEXT NOT NULL REFERENCES commands(key),account TEXT NOT NULL,debit_minor INTEGER NOT NULL CHECK(debit_minor BETWEEN 0 AND 99999999999999),credit_minor INTEGER NOT NULL CHECK(credit_minor BETWEEN 0 AND 99999999999999),PRIMARY KEY(command_key,account),CHECK((debit_minor=0)<>(credit_minor=0))) STRICT;
CREATE TABLE suppliers(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),name TEXT NOT NULL,reference TEXT NOT NULL UNIQUE,UNIQUE(id,store_id)) STRICT;
CREATE TABLE purchases(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),supplier_id TEXT NOT NULL,item_id TEXT NOT NULL REFERENCES catalog(id),quantity INTEGER NOT NULL CHECK(quantity>0),state TEXT NOT NULL DEFAULT 'POLICY_BLOCKED' CHECK(state IN('DRAFT','POLICY_BLOCKED','AUTHORIZED','RECEIVED')),FOREIGN KEY(supplier_id,store_id) REFERENCES suppliers(id,store_id)) STRICT;
-- No browser/direct public SQL access. Confidential projection is server-only.
CREATE TABLE confidential_purchase_finance(purchase_id TEXT PRIMARY KEY REFERENCES purchases(id),cost_minor INTEGER CHECK(cost_minor BETWEEN 1 AND 99999999999999),obligation_minor INTEGER CHECK(obligation_minor BETWEEN 0 AND 99999999999999)) STRICT;
CREATE TABLE receiving(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),quantity INTEGER NOT NULL CHECK(quantity>0),evidence_key TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES accounts(id)) STRICT;
CREATE TABLE debts(id TEXT PRIMARY KEY,customer_id TEXT NOT NULL REFERENCES customers(id),sale_id TEXT NOT NULL REFERENCES sales(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),state TEXT NOT NULL DEFAULT 'POLICY_BLOCKED' CHECK(state IN('DRAFT','POLICY_BLOCKED','AUTHORIZED'))) STRICT;
CREATE TABLE repayments(id TEXT PRIMARY KEY,debt_id TEXT NOT NULL REFERENCES debts(id),amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),reference TEXT NOT NULL UNIQUE,state TEXT NOT NULL CHECK(state IN('DRAFT','POLICY_BLOCKED','RECORDED'))) STRICT;
CREATE TRIGGER repayment_cap BEFORE INSERT ON repayments WHEN NEW.amount_minor+COALESCE((SELECT sum(amount_minor) FROM repayments WHERE debt_id=NEW.debt_id),0)>(SELECT amount_minor FROM debts WHERE id=NEW.debt_id) BEGIN SELECT RAISE(ABORT,'REPAYMENT_CAP'); END;
CREATE TABLE transfers(id TEXT PRIMARY KEY,source_store TEXT NOT NULL REFERENCES stores(id),destination_store TEXT NOT NULL REFERENCES stores(id),stage TEXT NOT NULL CHECK(stage IN('DRAFT','APPROVALS','DISPATCH','IN_TRANSIT','RECEIPT','COMPLETED','POLICY_BLOCKED')),CHECK(source_store<>destination_store)) STRICT;
CREATE TABLE transfer_lines(transfer_id TEXT NOT NULL REFERENCES transfers(id),item_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('phone','accessory')),quantity INTEGER NOT NULL CHECK(quantity>0),code TEXT NOT NULL,PRIMARY KEY(transfer_id,item_id)) STRICT;
CREATE TABLE transfer_approvals(transfer_id TEXT NOT NULL REFERENCES transfers(id),approval TEXT NOT NULL CHECK(approval IN('SUPER_ADMIN','M02_MANAGER')),actor_id TEXT NOT NULL REFERENCES accounts(id),PRIMARY KEY(transfer_id,approval),UNIQUE(transfer_id,actor_id)) STRICT;
CREATE TABLE transfer_scans(transfer_id TEXT NOT NULL REFERENCES transfers(id),item_id TEXT NOT NULL,code TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(transfer_id,item_id),FOREIGN KEY(transfer_id,item_id) REFERENCES transfer_lines(transfer_id,item_id)) STRICT;
CREATE TABLE facilities(id TEXT PRIMARY KEY,store_id TEXT NOT NULL CHECK(store_id='M01') REFERENCES stores(id),customer_id TEXT NOT NULL,employer TEXT NOT NULL,cash_price_minor INTEGER NOT NULL CHECK(cash_price_minor>0),contract_price_minor INTEGER NOT NULL CHECK(contract_price_minor>0),state TEXT NOT NULL CHECK(state IN('DRAFT','POLICY_BLOCKED')),FOREIGN KEY(customer_id,store_id) REFERENCES customers(id,store_id)) STRICT;
CREATE TABLE installments(facility_id TEXT NOT NULL REFERENCES facilities(id),month TEXT NOT NULL,amount_minor INTEGER NOT NULL CHECK(amount_minor BETWEEN 1 AND 99999999999999),PRIMARY KEY(facility_id,month)) STRICT;
CREATE TABLE facility_evidence(id TEXT PRIMARY KEY,facility_id TEXT NOT NULL REFERENCES facilities(id),kind TEXT NOT NULL CHECK(kind IN('SALARY_DEDUCTION','BANK_REMITTANCE')),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),document_key TEXT NOT NULL,state TEXT NOT NULL CHECK(state='UNVERIFIED')) STRICT;
CREATE TABLE service_cases(id TEXT PRIMARY KEY,sale_id TEXT NOT NULL REFERENCES sales(id),phone_id TEXT NOT NULL REFERENCES phones(id),customer_id TEXT NOT NULL REFERENCES customers(id),state TEXT NOT NULL CHECK(state IN('INSPECTION','POLICY_BLOCKED')),issue TEXT NOT NULL,UNIQUE(sale_id,phone_id)) STRICT;
CREATE TABLE service_events(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES service_cases(id),actor_id TEXT NOT NULL REFERENCES accounts(id),note TEXT NOT NULL,evidence_key TEXT NOT NULL) STRICT;
CREATE TABLE expenses(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),evidence_key TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('DRAFT','POLICY_BLOCKED'))) STRICT;
CREATE TABLE documents(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),object_key TEXT NOT NULL UNIQUE,owner_id TEXT NOT NULL REFERENCES accounts(id),mime TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('PENDING','AVAILABLE','QUARANTINED'))) STRICT;
CREATE TABLE settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL CHECK(json_valid(value_json))) STRICT;